<script setup lang="ts">
import { computed, ref } from 'vue'
import { Upload, FolderOpen, FileText, Plus, X, CheckCircle2, CircleAlert, LoaderCircle, ShieldCheck, HardDrive, CopyPlus } from 'lucide-vue-next'
import type { ImportEntry } from '../lib/matterFlow'
const props=defineProps<{ matterName:string; entries:ImportEntry[]; processing:boolean; started:boolean; checking:boolean; blocked:boolean; cancelPending:boolean }>()
const emit=defineEmits<{add:[files:File[]];remove:[id:number];include:[id:number];start:[];retry:[];cancel:[];review:[];back:[]}>()
const input=ref<HTMLInputElement|null>(null)
const over=ref(false)
const ready=computed(()=>props.entries.filter(e=>e.status==='ready').length)
const completed=computed(()=>props.entries.filter(e=>e.status==='complete').length)
const attempted=computed(()=>props.entries.filter(e=>['complete','failed','cancelled'].includes(e.status)).length)
const total=computed(()=>props.entries.filter(e=>!['unsupported','duplicate','oversize'].includes(e.status)).length)
const percentage=computed(()=>total.value?Math.round(attempted.value/total.value*100):0)
function add(files: FileList|null){ if(files)emit('add',Array.from(files));if(input.value)input.value.value='' }
function drop(e:DragEvent){over.value=false;if(!props.processing)add(e.dataTransfer?.files||null)}
function status(e:ImportEntry){return e.message || ({ready:'Ready',unsupported:'Unsupported · excluded',oversize:'Over 80 MB · excluded',duplicate:'Identical file · excluded',processing:'Creating working copy',complete:'Complete',failed:'Import failed',cancelled:'Cancelled'}[e.status])}
</script>
<template>
<section class="import-workspace flow-page" aria-label="Import documents" :data-started="started">
  <header class="flow-heading"><div><h1>{{processing?'Importing documents':started?'Import results':'Import documents'}}</h1><p>{{processing?'Reading files and creating working copies on this computer.':`${matterName} · Imported originals are preserved.`}}</p></div><span v-if="processing" class="flow-muted import-local"><HardDrive :size="16"/>Local processing</span></header>
  <input ref="input" aria-label="Choose import files" type="file" multiple hidden @change="add(($event.target as HTMLInputElement).files)"/>
  <div v-if="!started" class="import-drop" :class="{over}" @dragover.prevent="over=true" @dragleave="over=false" @drop.prevent="drop"><Upload :size="24"/><div><h2>Drop files here, or choose files</h2><p>PDF, JPEG and PNG · Multiple files supported · Local processing</p></div><button class="btn secondary" :disabled="checking||blocked" @click="input?.click()"><FolderOpen :size="15"/>Choose files</button></div>
  <div v-else class="import-progress" aria-live="polite"><div><h2>{{completed}} of {{total}} files imported</h2><strong>{{percentage}}%</strong></div><progress :value="attempted" :max="total||1" aria-label="Import progress"/><p>{{completed}} complete · {{entries.filter(e=>e.status==='processing').length}} processing · {{ready}} queued<span v-if="entries.some(e=>e.status==='failed')"> · {{entries.filter(e=>e.status==='failed').length}} failed</span></p></div>
  <div class="flow-section-heading"><h2>{{started?'Processing queue':'Import queue'}}</h2><span aria-live="polite">{{checking?'Checking files…':`${entries.length} selected · ${ready} ${started?'queued':'will be imported'} · ${entries.filter(e=>['unsupported','duplicate','oversize'].includes(e.status)).length} excluded`}}</span></div>
  <div class="import-table-scroll"><table class="flow-table import-table"><thead><tr><th>File</th><th>{{started?'Source pages':'Format'}}</th><th>{{started?'Current stage':'Status'}}</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="entry in (started?entries.filter(e=>!['unsupported','duplicate','oversize'].includes(e.status)):entries)" :key="entry.id"><td><div class="import-file-name"><FileText :size="16"/><span :title="entry.file.name">{{entry.file.name}}</span></div></td><td>{{started?(entry.pages??(entry.status==='processing'?'Reading…':'—')):entry.file.name.split('.').pop()?.toUpperCase()}}</td><td><span class="flow-status" :data-status="entry.status"><LoaderCircle v-if="entry.status==='processing'" :size="13" class="spin"/><CheckCircle2 v-else-if="['ready','complete'].includes(entry.status)" :size="13"/><CircleAlert v-else :size="13"/>{{status(entry)}}</span></td><td><button v-if="!started" class="icon-btn small" :disabled="checking" :aria-label="`Remove ${entry.file.name}`" @click="emit('remove',entry.id)"><X :size="14"/></button><button v-if="entry.status==='duplicate'&&!started" class="icon-btn small include-duplicate" aria-label="Include duplicate" title="Include this duplicate file" @click="emit('include',entry.id)"><CopyPlus :size="14"/></button></td></tr><tr v-if="!entries.length"><td colspan="4" class="import-empty">Choose files to review them before importing.</td></tr></tbody></table></div>
  <p class="flow-muted import-note">{{started?'Completed imports remain in this matter. Originals are unchanged.':'Excluded files will stay outside this matter. Imported documents start as reference-only.'}}</p>
  <footer class="flow-footer"><template v-if="!started"><button class="btn secondary" :disabled="checking||blocked" @click="input?.click()"><Plus :size="15"/>Add more</button><span class="flow-muted">Review the queue, then import.</span><button class="btn secondary push-right" :disabled="checking" @click="emit('back')">Cancel</button><button class="btn primary" :disabled="!ready||checking||blocked" @click="emit('start')"><Upload :size="15"/>Import {{ready}} {{ready===1?'file':'files'}}</button></template><template v-else><ShieldCheck :size="16"/><span class="flow-muted">Original files are unchanged.</span><button v-if="processing" class="btn secondary push-right" :disabled="cancelPending" @click="emit('cancel')">{{cancelPending?'Stopping after current file…':'Cancel remaining imports'}}</button><template v-else><button v-if="entries.some(e=>['failed','cancelled'].includes(e.status))" class="btn secondary" @click="emit('retry')">Retry remaining files</button><button class="btn secondary push-right" @click="emit('back')">Back to overview</button><button class="btn primary" @click="emit('review')">Continue to document review</button></template></template></footer>
</section>
</template>
